// La version protège contre le lost update
class Account {
    private long version;   // incrémentée à chaque écriture
    private Money balance;
}

// À la sauvegarde (esprit du SQL généré par l'ORM) :
// UPDATE account SET balance = ?, version = version + 1
// WHERE id = ? AND version = ?   -- la version lue
// Si 0 ligne affectée -> quelqu'un a modifié entre-temps -> conflit
// (en JPA : @Version ; on capture OptimisticLockException)
